20	     * @param randomAge Whether the animal should have a random age or not.
21	     * @param field The field in which this animal resides.
22	     * @param location The location in which this animal spawns into.
23	     */
24	    public HungryAnimal(int foodLevel, boolean randomAge, Field field, Location location) {
25	        super(randomAge, field, location);
26	        this.foodLevel = foodLevel;
27	    }
28	
29	    /**
30	     * Shared hunting turn for predator and scavenger animals.
31	     *
32	     * @param newAnimals Newly born organisms from this turn.
33	     * @param time The current simulation time.
34	     * @param restingTime The time of day when this animal stops acting.
35	     */
36	    @Override
37	    public void act(List<Entity> newAnimals, Weather weather, TimeOfDay time) {
38	        incrementAge();
39	        incrementHunger();
40	
41	        if (!isAlive()) {
42	            return;
43	        }
44	
45	        giveBirth(newAnimals);
46	
47	        if (time == restingTime()) {
48	            return;
49	        }
50	
51	        if (rand.nextDouble() <= getDeathByDiseaseProbability()) {
52	            remove();
53	            return;
54	        }
55	
56	        Location newLocation;
57	        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
58	            newLocation = findAnimalToInfect();
59	        } else {
60	            newLocation = findFood();
61	        }
62	
63	        if (newLocation == null) {
64	            newLocation = getField().freeAdjacentLocation(getLocation());
65	        }
66	
67	        if (newLocation != null) {
68	            setLocation(newLocation);
69	        } else {
70	            remove();
71	        }
72	    }
73	
74	    /**
75	     * The time of day when this animal does not act.
76	     *
77	     * @return The resting time.
78	     */
79	    protected abstract TimeOfDay restingTime();
80	
81	    /**
82	     * Increment the food level of this animal by a given amount.
83	     *
84	     * @param foodLevel The value to increment food level by.
85	     */
86	    protected void incrementFoodLevel(int foodLevel) {
87	        this.foodLevel += foodLevel;
88	    }
